function draftSignature(draft=state.draft){return JSON.stringify({programId:String(draft?.programId||""),name:String(draft?.name||""),blocks:draft?.blocks||[]});}
function updateSaveActions(){const existing=Boolean(state.draft?.programId);$("#saveProgramButton")?.classList.toggle("is-hidden",existing);$("#overwriteProgramButton")?.classList.toggle("is-hidden",!existing);$("#saveAsNewProgramButton")?.classList.toggle("is-hidden",!existing);}
