function newDraft(){state.draft={programId:"",name:"新しい駒",blocks:[]};state.moveSource=null;state.copySource=null;resetInsertionCursor();markDraftSaved();renderWorkspace();}
function openProgram(id){const p=state.programs.find(x=>x.programId===id);if(!p)return;state.draft={programId:p.programId,name:p.name,blocks:deepClone(p.blocks||[])};state.selectedProgramId=p.programId;state.moveSource=null;state.copySource=null;resetInsertionCursor();markDraftSaved();showView("editor",true);}
const lit=(value)=>({type:"literal",value});
