function renderBoard(el,game,previous=null){if(!el)return;const size=game.size;if(Number(el.dataset.size)!==size||el.children.length!==size*size){el.innerHTML="";el.dataset.size=String(size);el.style.gridTemplateColumns=`repeat(${size},1fr)`;for(let i=0;i<size*size;i++){const c=document.createElement("div");c.className="board-cell";c.dataset.x=String(i%size);c.dataset.y=String(Math.floor(i/size));el.append(c);}}const occupied=new Map((game.agents||[]).filter(a=>a.alive).map(a=>[`${a.x},${a.y}`,a])),tails=new Map();for(const a of(game.agents||[]))for(const t of(a.tail||[]))tails.set(`${t.x},${t.y}`,a.color);const effects=new Map((game.effects||[]).map(e=>[`${e.x},${e.y}`,e]));for(let y=0;y<size;y++)for(let x=0;x<size;x++){const i=y*size+x,c=el.children[i],owner=game.board?.[y]?.[x]??-1,color=owner>=0?game.agents?.[owner]?.color:"";c.className=`board-cell${color?` claim-${color}`:""}`;if(!isPlayableCell(game,x,y)){c.classList.add("is-void");c.innerHTML="";continue;}if(game.holes?.has(`${x},${y}`))c.classList.add("is-hole");if(previous&&previous[y]?.[x]!==owner&&owner>=0)c.classList.add("just-claimed");const ef=effects.get(`${x},${y}`);if(ef?.type==="shot")c.classList.add("attack-flash",`attack-${ef.color}`);c.innerHTML="";const tc=tails.get(`${x},${y}`);if(tc){const t=document.createElement("span");t.className=`tail-piece ${tc}`;c.append(t);}const a=occupied.get(`${x},${y}`);if(a){const p=document.createElement("span");p.className=`piece ${a.color} dir-${a.dir}`;c.append(p);if(String(a.speech??"").length){const speech=document.createElement("span");speech.className=`piece-speech-bubble ${a.color}`;speech.textContent=String(a.speech).slice(0,80);c.append(speech);}if(state.showNames&&el.id==="battleBoard"){const label=document.createElement("span");label.className=`piece-name-label ${a.color}`;label.textContent=a.name;c.append(label);}}}}
function stopTest(message=""){if(state.testTimer)clearInterval(state.testTimer);state.testTimer=null;if(message&&$("#testStatus"))$("#testStatus").textContent=message;else if(state.view==="editor")setTimeout(renderTestPreview,0);}
function testNpcLabel(type){return({straight:"直進型",wall:"壁沿い型",explore:"探索型",evade:"回避型",chase:"追跡型",random:"ランダム型",beginner:"初級",intermediate:"中級",advanced:"上級"})[type]||"中級";}
function effectiveTestConfig(){if(isTutorial())return{mode:"territory",npcCount:0,npcType:"straight",boardShape:"square",boardSizeKey:"small",rollSeed:"tutorial-board",spawnMode:"fixed",spawnActor:"me",fixedSpawns:{me:{x:4,y:7,dir:1}}};return{mode:state.testMode,npcCount:Math.max(0,Math.min(3,Number(state.testNpcCount)||0)),npcType:state.testNpcType,boardShape:state.testBoardShape,boardSizeKey:state.testBoardSizeKey,rollSeed:state.testRollSeed,spawnMode:state.testSpawnMode,spawnActor:state.testSpawnActor,fixedSpawns:deepClone(state.testFixedSpawns)};}
function resolvedTestBoard(c){return createBoardDefinition({boardShape:c.boardShape,boardSizeKey:c.boardSizeKey,seed:`${c.rollSeed}:board`});}
function testNpcKeys(c){return Array.from({length:Math.max(0,Math.min(3,Number(c.npcCount)||0))},(_,i)=>`npc${i+1}`);}
function fixedSpawnKeys(c){return["me",...testNpcKeys(c)];}
function selectedFixedSpawn(c){const keys=fixedSpawnKeys(c),key=keys.includes(c.spawnActor)?c.spawnActor:"me";return{key,spawn:c.fixedSpawns[key]};}
function testSpawns(c,count,def=resolvedTestBoard(c)){if(c.spawnMode==="random")return createRandomSpawns(def,count,`${c.rollSeed}:random-spawns`);if(c.spawnMode==="battle")return createBattleSpawns(def,count,`${c.rollSeed}:battle-spawns`);const spawns=fixedSpawnKeys(c).slice(0,count).map(key=>c.fixedSpawns[key]);return validateSpawnList(def,spawns,count)?spawns.map(s=>({...s})):null;}
function invalidateTestFixedSpawns(){const c=effectiveTestConfig(),def=resolvedTestBoard(c),seen=new Set();for(const key of fixedSpawnKeys(c)){const s=state.testFixedSpawns[key];if(!s)continue;if(s.x!=null&&!isPlayableCell(def,Number(s.x),Number(s.y))){s.x=null;s.y=null;continue;}if(s.x==null)continue;const pos=`${s.x},${s.y}`;if(seen.has(pos)){s.x=null;s.y=null;continue;}seen.add(pos);}}
function previewGame(c){const def=resolvedTestBoard(c),count=1+c.npcCount,spawns=testSpawns(c,count,def),board=Array.from({length:def.size},()=>Array(def.size).fill(-1)),agents=[];const defs=[{key:"me",name:"あなた",color:PLAYER_COLORS[0]},...testNpcKeys(c).map((key,i)=>({key,name:`NPC${i+1}・${testNpcLabel(c.npcType)}`,color:PLAYER_COLORS[i+1]}))];const previewSpawns=spawns||defs.map(d=>c.fixedSpawns[d.key]);for(const d of defs){const s=previewSpawns[defs.indexOf(d)];if(!s||s.x==null||!isPlayableCell(def,Number(s.x),Number(s.y)))continue;const index=agents.length;agents.push({id:d.key,name:d.name,color:d.color,x:Number(s.x),y:Number(s.y),dir:Number(s.dir)||0,alive:true,tail:[]});if(c.mode==="territory"||c.mode==="splat")board[Number(s.y)][Number(s.x)]=index;}return{mode:c.mode,size:def.size,boardShape:def.shape,boardSizeKey:def.sizeKey,mask:def.mask,playableCount:def.playableCount,board,agents,holes:new Set(),effects:[]};}
function renderTestPreview(){if(state.testTimer)return;const c=effectiveTestConfig(),game=previewGame(c),def=resolvedTestBoard(c);state.testGame=game;renderBoard($("#testBoard"),game);$("#testBoardMeta").textContent=`${def.size} × ${def.size} ・ ${boardChoiceLabel(def.shape,def.sizeKey)}`;}
function updateTestBenchUI(){const c=effectiveTestConfig(),def=resolvedTestBoard(c),selected=selectedFixedSpawn(c),fixed=c.spawnMode==="fixed";$$('[data-test-mode]').forEach(b=>b.classList.toggle('is-selected',b.dataset.testMode===c.mode));$("#testNpcCount").value=String(c.npcCount);$("#testNpcType").value=c.npcType;$("#testBoardShape").value=c.boardShape;$("#testBoardSizeKey").value=c.boardSizeKey;$("#testSpawnMode").value=c.spawnMode;$("#testSpawnActor").value=selected.key;$("#testSpawnDirection").value=String(Number(selected.spawn?.dir)||0);$("#testNpcTypeRow").classList.toggle("is-hidden",c.npcCount===0);$("#testSpawnActorRow").classList.toggle("is-hidden",!(fixed&&c.npcCount>0));const actor=$("#testSpawnActor"),keys=fixedSpawnKeys(c);if(!keys.includes(state.testSpawnActor))state.testSpawnActor="me";actor.innerHTML="";for(const key of keys)actor.add(new Option(key==="me"?"あなた":`NPC${key.slice(3)}`,key));actor.value=selected.key;$("#testDirectionRow").classList.toggle("is-hidden",!fixed);$("#testSpawnHint").classList.toggle("is-hidden",!fixed);if(fixed){const missing=selected.spawn?.x==null;$("#testSpawnHint").textContent=missing?`${selected.key==="me"?"あなた":`NPC${selected.key.slice(3)}`}の開始マスを盤面上で指定してください。`:`${selected.key==="me"?"あなた":`NPC${selected.key.slice(3)}`}：(${selected.spawn.x}, ${selected.spawn.y}) ・ 盤面タップで変更`;$("#testSpawnHint").classList.toggle("is-warning",missing);}const requested=boardChoiceLabel(c.boardShape,c.boardSizeKey),resolved=(c.boardShape==="random"||c.boardSizeKey==="random")?` → ${boardChoiceLabel(def.shape,def.sizeKey)}`:"";$("#testSettingsSummary").textContent=`${c.npcCount?`NPC ${c.npcCount}体・${testNpcLabel(c.npcType)}`:"NPCなし"} ・ ${requested}${resolved} ・ ${c.spawnMode==="fixed"?"指定":c.spawnMode==="battle"?"対戦配置":"ランダム配置"}`;renderTestPreview();}
function setTestMode(mode){if(MODES.includes(mode)){state.testMode=mode;updateTestBenchUI();}}
function openCommandHelp(kind){const content=kind==="attack"?["攻撃","主にスプラモードで使用します。スプラ以外のモード、射程が1未満、インク不足などで攻撃できなかった場合はタイマーを消費せず、そのまま次の命令の判定へ進みます。"]:["説明","この命令の説明は準備中です。"],o=document.createElement("div");o.className="expression-overlay info-overlay";o.innerHTML=`<div class="expression-card info-card"><h3>${content[0]}</h3><p>${content[1]}</p><button class="primary-button" type="button">閉じる</button></div>`;o.querySelector("button").onclick=()=>o.remove();document.body.append(o);}
function openTestModeHelp(){const mode=effectiveTestConfig().mode,[title,text]=MODE_DESCRIPTIONS[mode],o=document.createElement("div");o.className="expression-overlay info-overlay";o.innerHTML=`<div class="expression-card mode-help-card"><small>テストモード</small><h3>${title}</h3><p>${text}</p><p class="mode-help-question">${title}モードのチュートリアルを行いますか？</p><div class="expression-actions"><button class="secondary-button" type="button" data-close>説明だけ見る</button><button class="primary-button" type="button" data-start>チュートリアルを始める</button></div></div>`;o.querySelector('[data-close]').onclick=()=>o.remove();o.querySelector('[data-start]').onclick=()=>{o.remove();startOptional(mode)};document.body.append(o);}
function runTest(){stopTest();let c=effectiveTestConfig();if(!isTutorial()&&(c.spawnMode==="random"||c.spawnMode==="battle"||c.boardShape==="random"||c.boardSizeKey==="random")){state.testRollSeed=freshSeed();c=effectiveTestConfig();}const def=resolvedTestBoard(c),program=deepClone(state.draft.blocks),players=[{id:"me",name:"あなた",color:PLAYER_COLORS[0],program}];for(let i=0;i<c.npcCount;i++)players.push({id:`test-npc-${i+1}`,name:`NPC${i+1}・${testNpcLabel(c.npcType)}`,color:PLAYER_COLORS[i+1],program:makeTestNpcProgram(c.mode,c.npcType,i)});const spawns=testSpawns(c,players.length,def);if(c.spawnMode==="fixed"&&!spawns){updateTestBenchUI();return toast("指定スポーンを全員分設定してください");}let game;try{game=createGameState({mode:c.mode,seed:isTutorial()?"tutorial-test-v5":state.testRollSeed,size:def.size,boardShape:def.shape,boardSizeKey:def.sizeKey,maxTicks:Number.MAX_SAFE_INTEGER,stagnationTicks:Number.MAX_SAFE_INTEGER,allowSolo:!c.npc,players,spawns});}catch(e){console.error(e);return toast("スポーン位置を確認してください");}state.testGame=game;renderBoard($("#testBoard"),game);$("#testBoardMeta").textContent=`${game.size} × ${game.size} ・ ${boardChoiceLabel(game.boardShape,game.boardSizeKey)}`;$("#testStatus").textContent=`実行中 ・ ${MODE_LABELS[c.mode]} ・ ${c.npcCount?`NPC ${c.npcCount}体・${testNpcLabel(c.npcType)}`:"NPCなし"}`;const step=Number(state.profile?.tutorialStep||0);let halted=0;state.testTimer=setInterval(()=>{const prev=game.board?.map(r=>[...r]);stepGame(game);renderBoard($("#testBoard"),game,prev);const a=game.agents[0],stopped=a?.alive&&a.vm?.halted===true&&(c.mode==="territory"||c.mode==="splat");halted=stopped?halted+1:0;if(isTutorial()&&step===10&&a.alive&&game.tick>=30){stopTest();state.tutorialFinalPassed=true;$("#testStatus").textContent="成功：崖を判断して走り続けられました。駒を保存してください。";renderTutorial();return;}if(!a?.alive||game.finished||halted>=2){const reason=!a?.alive?(a.deathReason==="cliff"?"崖から落ちました":"ゲームオーバー"):halted>=2?"コードの末尾まで実行して停止しました":game.finishReason||"ゲーム終了";stopTest(`テスト終了：${reason}（タイマー ${game.tick}）`);if(isTutorial()&&step===2&&halted>=2&&game.tick<=4)tutorialProgress(3);else if(isTutorial()&&step===4&&!a.alive&&a.deathReason==="cliff")tutorialProgress(5);}},120);}
function showView(name,force=false){setMobilePalette(false);if(!force&&isTutorial()&&name==="battle"){toast("最初に駒作りのチュートリアルを完了してください");return;}stopTest();if(name!=="battle"&&name!=="result")stopBattle();state.view=name;$$('.view').forEach(v=>v.classList.toggle("is-active",v.dataset.view===name));$$('.nav-item').forEach(b=>b.classList.toggle("is-active",b.dataset.go===name));if(name==="editor")renderWorkspace();if(name==="battle")resetBattleSetup();updateMobilePaletteAvailability();renderTutorial();window.scrollTo({top:0,behavior:"smooth"});}
function renderHome(){const p=$("#homePrograms");p.innerHTML="";if(!state.programs.length){p.className="stack-list empty-state";p.textContent="まだ保存された駒はありません。";}else{p.className="stack-list";state.programs.slice(0,6).forEach(x=>{const row=document.createElement("div");row.className="list-row";row.innerHTML=`<div><strong>${esc(x.name)}</strong><br><small>${countBlocks(x.blocks||[])}ブロック</small></div><button class="text-button">編集</button>`;row.querySelector("button").onclick=()=>openProgram(x.programId);p.append(row);});}const m=$("#homeMatches");m.innerHTML="";if(!state.matches.length){m.className="stack-list empty-state";m.textContent="対戦記録はまだありません。";}else{m.className="stack-list";state.matches.slice(0,6).forEach(x=>{const row=document.createElement("div");row.className="list-row";row.innerHTML=`<div><strong>${esc(MODE_LABELS[x.mode]||"対戦")}</strong><br><small>Seed ${esc(x.seed||"")}</small></div>${x.replayId?`<button class="text-button" type="button">再生</button>`:"<span></span>"}`;const replayButton=row.querySelector("button");if(replayButton)replayButton.onclick=()=>replayMatch(x.replayId);m.append(row);});}}
function renderProgramChoices(){const host=$("#battleProgramList");if(!host)return;host.innerHTML="";if(!state.programs.length){host.className="program-select-list empty-state";host.textContent="先に駒を保存してください。";return;}if(!state.programs.some(p=>p.programId===state.selectedProgramId))state.selectedProgramId=state.programs[0].programId;for(const p of state.programs){const b=document.createElement("button");b.type="button";b.className=`program-choice${p.programId===state.selectedProgramId?" is-selected":""}`;b.innerHTML=`<span><strong>${esc(p.name)}</strong><br><small>${countBlocks(p.blocks||[])}ブロック</small></span>`;b.onclick=()=>{state.selectedProgramId=p.programId;renderProgramChoices()};host.append(b);}}
function canSaveDraft(){if(!state.user){toast("ログイン情報を取得できていません");setModal("#authModal",true);return false;}if(isTutorial()&&!state.tutorialFinalPassed){toast("最後にテストを成功させてください");return false;}return true;}
function openNamedSave(asNew=false,afterSave=null){if(!canSaveDraft())return;state.saveModalMode=asNew?"copy":"new";state.pendingAfterSave=afterSave;$("#saveProgramName").value=asNew?"":(state.draft.name==="新しい駒"?"":state.draft.name);$("#saveProgramError").textContent="";setModal("#saveProgramModal",true);}
function closeNamedSave(){state.pendingAfterSave=null;state.saveModalMode="new";setModal("#saveProgramModal",false);}
function openSave(){if(state.draft.programId)return void overwriteDraft();openNamedSave(false);}
function openSaveAsNew(){openNamedSave(true);}
async function persistDraft({programId,name,closeModal=false,afterSave=null}={}){if(!state.user)return false;try{const d=await api("/api/now-coding/programs",{method:"POST",body:JSON.stringify({userTrackingId:state.user.userTrackingId,programId:programId||"",name,blocks:state.draft.blocks})});const ix=state.programs.findIndex(p=>p.programId===d.program.programId);if(ix>=0)state.programs[ix]=d.program;else state.programs.unshift(d.program);state.selectedProgramId=d.program.programId;state.draft={programId:d.program.programId,name:d.program.name,blocks:deepClone(d.program.blocks)};markDraftSaved();const next=afterSave||state.pendingAfterSave;state.pendingAfterSave=null;state.saveModalMode="new";if(closeModal)setModal("#saveProgramModal",false);if(isTutorial())await tutorialProgress(TUTORIAL_STEPS.length,true);renderHome();renderProgramChoices();renderWorkspace();toast("駒を保存しました");if(next){next();return true;}if(isTutorial())showView("home",true);return true;}catch(e){const message=e.message==="program_too_large"?"コードが大きすぎます。":"保存に失敗しました。";if(closeModal)$("#saveProgramError").textContent=message;else toast(message);return false;}}
async function overwriteDraft(afterSave=null){if(!canSaveDraft())return false;if(!state.draft.programId){openNamedSave(false,afterSave);return false;}return persistDraft({programId:state.draft.programId,name:state.draft.name,afterSave});}
async function saveDraft(){if(!state.user){$("#saveProgramError").textContent="ログイン情報を取得できていません。";return;}const name=$("#saveProgramName").value.trim();if(!name){$("#saveProgramError").textContent="駒の名前を入力してください。";return;}const programId=state.saveModalMode==="copy"?"":(state.draft.programId||"");await persistDraft({programId,name,closeModal:true});}
function discardDraftChanges(){const saved=state.draft.programId?state.programs.find(p=>p.programId===state.draft.programId):null;state.draft=saved?{programId:saved.programId,name:saved.name,blocks:deepClone(saved.blocks||[])}:{programId:"",name:"新しい駒",blocks:[]};markDraftSaved();renderWorkspace();}
function requestUnsavedAction(action){if(state.view!=="editor"||!isDraftDirty()){action();return;}document.querySelectorAll(".unsaved-code-overlay").forEach(n=>n.remove());const o=document.createElement("div");o.className="expression-overlay info-overlay unsaved-code-overlay";o.innerHTML=`<div class="expression-card info-card unsaved-code-card"><small>未保存のコードがあります</small><h3>コードを保存しますか？</h3><p>コードの保存が出来ていません。<br>このページから移動してもよろしいですか？</p><div class="unsaved-code-actions"><button class="primary-button" type="button" data-save-move>保存して移動</button><button class="secondary-button" type="button" data-discard-move>保存せず移動</button><button class="text-button" type="button" data-cancel-move>キャンセル</button></div></div>`;o.querySelector("[data-save-move]").onclick=async()=>{o.remove();if(state.draft.programId)await overwriteDraft(action);else openNamedSave(false,action);};o.querySelector("[data-discard-move]").onclick=()=>{o.remove();discardDraftChanges();action();};o.querySelector("[data-cancel-move]").onclick=()=>o.remove();o.onclick=e=>{if(e.target===o)o.remove();};document.body.append(o);}


async function saveMatchRecord(game,results,{online=false,seriesId="",roundIndex=0,totalRounds=1}={}){
  if(!state.user?.userTrackingId)return null;
  if(online&&state.currentOnlineMeta?.saveOwnerId&&state.currentOnlineMeta.saveOwnerId!==state.user.userTrackingId)return null;
  const participants=game.agents.map(a=>({userTrackingId:a.userTrackingId||"",username:a.name,color:a.color}));
  const programs=game.agents.map(a=>({id:a.id,userTrackingId:a.userTrackingId||"",name:a.name,color:a.color,programName:a.programName||"",program:a.program}));
  try{
    const saved=await api("/api/now-coding/matches",{method:"POST",body:JSON.stringify({
      userTrackingId:state.user.userTrackingId,mode:game.mode,seed:game.seed,
      settings:{size:game.size,boardShape:game.boardShape||"square",boardSizeKey:game.boardSizeKey||"custom",playableCount:game.playableCount||game.size*game.size,playerCount:game.agents.length,maxTicks:game.maxTicks,online,seriesId,roundIndex,totalRounds},
      participants,results,programs,spawn:game.spawns||[],durationTicks:game.tick,finishReason:game.finishReason,ruleVersion:game.ruleVersion||"now-coding-v3"
    })});
    state.matches.unshift({matchId:saved.matchId,replayId:saved.replayId,mode:game.mode,seed:game.seed,settings:{size:game.size,boardShape:game.boardShape||"square",boardSizeKey:game.boardSizeKey||"custom",seriesId,roundIndex,totalRounds},results,createdAt:new Date().toISOString()});
    renderHome();return saved;
  }catch(error){console.warn("match save failed",error);toast("対戦記録の保存に失敗しました");return null;}
}
async function replayMatch(replayId){
  if(!replayId||!state.user)return;
  try{
    const d=await api(`/api/now-coding/replays/${encodeURIComponent(replayId)}?userTrackingId=${encodeURIComponent(state.user.userTrackingId)}`);
    const r=d.replay;const players=(r.programs||[]).map((p,i)=>({id:p.id||`p${i}`,userTrackingId:p.userTrackingId||"",name:p.name||`駒${i+1}`,color:p.color||PLAYER_COLORS[i],program:p.program||[]}));
    state.series=null;state.onlineSeries=null;state.currentOnlineMeta=null;showView("battle",true);startBattle({mode:r.mode||"territory",seed:r.seed,size:Number(r.settings?.size||21),boardShape:r.settings?.boardShape||null,boardSizeKey:r.settings?.boardSizeKey||null,players,spawns:r.spawn||null,maxTicks:Number(r.settings?.maxTicks||600)},true);
  }catch(error){console.error(error);toast("リプレイを読み込めませんでした");}
}
function boardChoiceFromControls(online=false){return{shape:$(online?"#onlineBoardShape":"#boardShape")?.value||"square",sizeKey:$(online?"#onlineBoardSizeKey":"#boardSizeKey")?.value||"large"};}
