function renderHud(game){$("#battleTick").textContent=String(game.tick);$("#scoreHud").innerHTML=gameResults(game).sort((a,b)=>a.rank-b.rank).map(r=>`<span class="score-chip"><i class="score-dot ${r.color}"></i>${esc(r.name)} ${esc(r.metric||r.score||"")}</span>`).join("");}
