function setMenu(open){$("#sideMenu").classList.toggle("is-open",open);$("#sideMenu").setAttribute("aria-hidden",open?"false":"true");$("#menuBackdrop").hidden=!open;}
function openTutorialLibrary(){const grid=$("#tutorialLibraryGrid");grid.innerHTML="";TUTORIALS.forEach(t=>{const b=document.createElement("button");b.className="tutorial-library-card";b.innerHTML=`<strong>${esc(t.title)}</strong><small>${esc(t.summary)}</small>`;b.onclick=()=>startOptional(t.id);grid.append(b)});setModal("#tutorialLibraryModal",true);}
function startOptional(id){const t=tutorialById(id);if(!t)return;setModal("#tutorialLibraryModal",false);state.optionalTutorial={id,step:0};if(t.mode)setTestMode(t.mode);showView(t.mode?"editor":(t.view||"editor"),true);if(t.battleKind)setBattleKind(t.battleKind);renderOptional();if(t.mode)setTimeout(()=>$("#testBoard")?.scrollIntoView({behavior:"smooth",block:"center"}),120);}
